.lang-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #0a0f1c 0%, #111827 40%, #0f172a 100%);
  padding: 1rem;
}
.lang-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1rem;
  padding: 2rem;
  width: 100%;
  max-width: 360px;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}
.title {
  color: #e2e8f0;
  font-size: 1.25rem;
  text-align: center;
  font-weight: 600;
}
.options {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.option-btn {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
  border-radius: 0.75rem;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: #e2e8f0;
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}
.option-btn:hover {
  background: rgba(255, 255, 255, 0.12);
}
.option-btn:active {
  transform: scale(0.98);
}
.flag {
  font-size: 1.3rem;
  line-height: 1;
}
.name {
  font-weight: 500;
}

